<script>
(()=>{const editor=document.getElementById('options-editor');if(!editor)return;const type=document.getElementById('question-type'),add=document.getElementById('add-option'),counter=document.getElementById('option-counter'),help=document.getElementById('correct-help');const initial=JSON.parse(editor.dataset.correct||'[]');const rows=()=>Array.from(editor.querySelectorAll('[data-option-row]'));const colors=['option-color-0','option-color-1','option-color-2','option-color-3'];function sync(){const kind=type.value;rows().forEach((row,i)=>{row.querySelector('.option-color').textContent=String.fromCharCode(65+i);row.querySelector('.option-color').className='option-color '+colors[i%4];const input=row.querySelector('[data-option-text]');input.name='options['+i+'][text]';const radio=row.querySelector('.correct-radio'),check=row.querySelector('.correct-check');radio.value=i;check.value=i;radio.style.display=kind==='multiple_choice'?'none':'inline-block';check.style.display=kind==='multiple_choice'?'inline-block':'none';row.querySelector('[data-remove-option]').disabled=rows().length<=2||kind==='true_false';});add.disabled=rows().length>=6||kind==='true_false';counter.textContent=rows().length+' / 6';help.textContent=kind==='multiple_choice'?'Marca todas las correctas.':'Marca una única respuesta correcta.';const warn=document.getElementById('length-bias-warning');if(warn)warn.hidden=true;}function addRow(text=''){let i=rows().length;const row=document.createElement('div');row.className='option-edit-row';row.setAttribute('data-option-row','');row.innerHTML='<span class="option-color '+colors[i%4]+'">'+String.fromCharCode(65+i)+'</span><input type="text" name="options['+i+'][text]" maxlength="500" placeholder="Alternativa '+(i+1)+'" data-option-text required><label class="correct-toggle"><input class="correct-radio" type="radio" name="correct_single" value="'+i+'"><input class="correct-check" type="checkbox" name="correct[]" value="'+i+'"><span class="correct-mark">✓</span></label><button class="remove-option" type="button" data-remove-option>×</button>';row.querySelector('input[data-option-text]').value=text;editor.appendChild(row);sync();}add.addEventListener('click',()=>addRow());editor.addEventListener('click',e=>{if(e.target.closest('[data-remove-option]')&&rows().length>2){e.target.closest('[data-option-row]').remove();sync();}});type.addEventListener('change',()=>{if(type.value==='true_false'){while(rows().length<2)addRow();while(rows().length>2)rows().at(-1).remove();rows()[0].querySelector('[data-option-text]').value='Verdadero';rows()[1].querySelector('[data-option-text]').value='Falso';}sync();});const form=editor.closest('form');form.addEventListener('submit',e=>{const current=rows();const kind=type.value;const selected=kind==='multiple_choice'?editor.querySelectorAll('.correct-check:checked').length:editor.querySelectorAll('.correct-radio:checked').length;if(current.some(r=>!r.querySelector('[data-option-text]').value.trim())||current.length<2||!selected){e.preventDefault();alert('Completa al menos dos alternativas y marca la respuesta correcta.');return;}if(kind==='single_choice'){const choice=editor.querySelector('.correct-radio:checked');if(choice){const hidden=document.createElement('input');hidden.type='hidden';hidden.name='correct[]';hidden.value=choice.value;form.appendChild(hidden);}}});initial.forEach(v=>{const input=editor.querySelector('.correct-check[value="'+v+'"]');if(input)input.checked=true;});sync();})();
</script>
